Float cosTheta = std::sqrt(1.0f - u[1] * u[1]); // This is not the standard projection.
// The standard way to generate a cosine-weighted sample by projecting a disk:
// 1. Sample a point on a unit disk
Float r = std::sqrt(u[1]);
Float x = r * std::cos(phi);
Float y = r * std::sin(phi);
// 2. Project the disk point onto the hemisphere
Float z = std::sqrt(std::max(0.0f, 1.0f - x * x - y * y));
return Vector3f(x, y, z);

